# PTX source for fp16 matrix multiplication (N x N) on SM80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N
)
{
    //----- parameter load -------------------------------------------------
    .reg .pred   p;
    .reg .u32    tid_x, tid_y, blk_x, blk_y;
    .reg .u64    a_ptr, b_ptr, c_ptr;
    .reg .u32    n;

    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 n,     [N];

    //----- thread/block indices -------------------------------------------
    mov.u32   tid_x, %tid.x;
    mov.u32   tid_y, %tid.y;
    mov.u32   blk_x, %ctaid.x;
    mov.u32   blk_y, %ctaid.y;

    //----- global row/col of the output element ---------------------------
    .reg .u32 row, col;
    mul.lo.u32 %r1, blk_y, 16;
    add.u32    row, %r1, tid_y;
    mul.lo.u32 %r2, blk_x, 16;
    add.u32    col, %r2, tid_x;

    //----- shared memory tiles (16x16 half) -------------------------------
    .shared .align 4 .b16 As[256];
    .shared .align 4 .b16 Bs[256];

    //----- accumulator (fp32) ---------------------------------------------
    .reg .f32 acc;
    mov.f32 acc, 0f0;

    //----- loop over K dimension in tiles of 16 --------------------------
    .reg .u32 k;
    mov.u32 k, 0;

K_LOOP:
    setp.ge.u32 p, k, n;
    @p bra END_K_LOOP;

    //--- load A tile element into shared memory -------------------------
    // global index: A[row, k + tid_x]
    .reg .u32 a_col, a_idx;
    mul.lo.u32 %r3, row, n;
    add.u32    a_col, k, tid_x;
    add.u32    a_idx, %r3, a_col;
    mul.wide.u32 %rd1, a_idx, 2;
    add.u64    %rdA, a_ptr, %rd1;
    ld.global.f16 %f1, [%rdA];

    // shared offset for As[tid_y][tid_x]
    mad.lo.u32 %r4, tid_y, 16, tid_x;      // index = tid_y*16 + tid_x
    shl.b64   %rd2, %r4, 1;                // byte offset = index*2
    st.shared.b16 [As + %rd2], %f1;

    //--- load B tile element into shared memory -------------------------
    // global index: B[k + tid_y, col]
    .reg .u32 b_row, b_idx;
    add.u32    b_row, k, tid_y;
    mul.lo.u32 %r5, b_row, n;
    add.u32    b_idx, %r5, col;
    mul.wide.u32 %rd3, b_idx, 2;
    add.u64    %rdB, b_ptr, %rd3;
    ld.global.f16 %f2, [%rdB];

    // shared offset for Bs[tid_y][tid_x]
    mad.lo.u32 %r6, tid_y, 16, tid_x;      // same layout as As
    shl.b64   %rd4, %r6, 1;
    st.shared.b16 [Bs + %rd4], %f2;

    //--- synchronize before compute --------------------------------------
    bar.sync 0;

    //--- compute partial dot product for this tile -----------------------
    .reg .u32 i;
    mov.u32 i, 0;

I_LOOP:
    setp.ge.u32 p, i, 16;
    @p bra END_I_LOOP;

    // load A shared element As[tid_y][i]
    mad.lo.u32 %r7, tid_y, 16, i;
    shl.b64   %rd5, %r7, 1;
    ld.shared.f16 %f3, [As + %rd5];

    // load B shared element Bs[i][tid_x]
    mad.lo.u32 %r8, i, 16, tid_x;
    shl.b64   %rd6, %r8, 1;
    ld.shared.f16 %f4, [Bs + %rd6];

    // convert to fp32 and multiply‑accumulate
    cvt.rn.f32.f16 %f5, %f3;
    cvt.rn.f32.f16 %f6, %f4;
    mul.f32 %f7, %f5, %f6;
    add.f32 acc, acc, %f7;

    add.u32 i, i, 1;
    bra I_LOOP;
END_I_LOOP:

    //--- synchronize before next K tile ----------------------------------
    bar.sync 0;

    add.u32 k, k, 16;
    bra K_LOOP;
END_K_LOOP:

    //----- write result if inside matrix bounds ---------------------------
    setp.ge.u32 p, row, n;
    @p bra END_WRITE;
    setp.ge.u32 p, col, n;
    @p bra END_WRITE;

    // compute address of C[row, col]
    .reg .u32 c_idx;
    mul.lo.u32 %r9, row, n;
    add.u32    c_idx, %r9, col;
    mul.wide.u32 %rd7, c_idx, 2;
    add.u64    %rdC, c_ptr, %rd7;

    // convert accumulator to half and store
    cvt.rn.f16.f32 %f8, acc;
    st.global.f16 [%rdC], %f8;

END_WRITE:
    ret;
}
'''

# Model wrapper that loads and launches the PTX kernel
class ModelNew:
    def __init__(self):
        # ptx_load is provided by the harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A, B):
        import torch
        assert A.is_contiguous() and B.is_contiguous()
        N = A.shape[0]
        C = torch.empty_like(A)

        # launch configuration: each block = 16x16 threads, grid covers N/16 tiles
        grid  = ((N + 15) // 16, (N + 15) // 16, 1)
        block = (16, 16, 1)

        # arguments: raw pointers and dimension
        args = [A.data_ptr(), B.data_ptr(), C.data_ptr(), N]

        # ptx_launch is provided by the harness
        ptx_launch(self.module, "matmul_kernel", grid, block, args)
        return C
